-- 2. their 15 details rows: proof hint, safety note, credit, quotation, source, licence
insert into public.action_mission_details
  (mission_id, catalog, slug, proof_hint, safety_note, credit_line, about, about_credit, source_url,
   license_name, license_url, doi)
select v.mission_id, 'drawdown', v.slug, v.proof_hint, v.safety_note, v.credit_line, v.about, v.about_credit,
       v.source_url, v.license_name, v.license_url, v.doi
  from (values
    ('6fae6f0d-c160-57ef-9977-3bed661fb77a'::uuid, 'drawdown-improve-nutrient-management',
     'A photo or link to your post or flyer with the official source.',
     'Link to the official rules instead of interpreting them yourself, put up flyers only where you have permission, and don''t handle or spread fertilizer for this mission.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-nutrient-management), used with permission; assessment "Improve Nutrient Management- Solution Assessment Spreadsheet" by Avery Driscoll, https://doi.org/10.5281/zenodo.21230979, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'We define the Improve Nutrient Management solution as reducing excessive nitrogen use on croplands. Nitrogen is critical for crop production and is added to croplands as synthetic or organic fertilizers and through microbial activity. However, farmers often add more nitrogen to croplands than crops can use.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-nutrient-management', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21230979'),
    ('1321d44c-b8ca-5f2e-975d-a7c1487d5cd0'::uuid, 'drawdown-improve-rice-production',
     'A link or photo of your explainer with sources listed.',
     'Stick to reliable sources, and don''t claim results your sources don''t support.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-rice-production), used with permission; assessment "Improve Rice Production- Solution Assessment Spreadsheet" by Eric Toensmeier and Zoltan Nagy, https://doi.org/10.5281/zenodo.21246058, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Rice production is a significant source of methane emissions and a minor source of nitrous oxide emissions. Most rice production occurs in flooded fields called paddies, where anaerobic conditions trigger high levels of methane production. This solution includes two related practices that each reduce emissions from paddy rice production: noncontinuous flooding and nutrient management.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-rice-production', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246058'),
    ('31490c0d-4a7a-5e86-a3a7-9904e1b872ad'::uuid, 'drawdown-improve-annual-cropping',
     'A photo or link to your guide with sources listed.',
     'Base it on reliable local sources, and plant only on land where you have permission.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-annual-cropping), used with permission; assessment "Improve Annual Cropping- Solution Assessment Spreadsheet" by Eric Toensme and Zoltan Nagy, https://doi.org/10.5281/zenodo.21246076, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Project Drawdown’s Improve Annual Cropping solution is a set of practices that protects soils by minimizing plowing (no-till/reduced tillage) and maintaining continuous soil cover (by retaining crop residues or growing cover crops). This increases soil carbon sequestration and reduces nitrous oxide emissions.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-annual-cropping', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246076'),
    ('5a898376-c3f7-57b3-9029-be155f809f2f'::uuid, 'drawdown-protect-coastal-wetlands',
     'Your map with links to the sources.',
     'Use public maps, and if you visit, check tide times, stay on boardwalks and don''t walk on marsh plants or seagrass.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/protect-coastal-wetlands), used with permission; assessment "Protect Coastal Wetlands- Solution Assessment Spreadsheet" by Christina Richardson and Avery Driscoll, https://doi.org/10.5281/zenodo.21246009, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Coastal wetland protection is the long-term protection of mangrove, salt marsh, and seagrass ecosystems from degradation by human activities. This solution focuses on legal mechanisms of coastal wetland protection, including the establishment of Protected Areas (PAs) and Marine Protected Areas (MPAs), which are managed with the primary goal of conserving nature.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/protect-coastal-wetlands', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246009'),
    ('e459b18c-7352-5f7c-b93c-d5cb383f850c'::uuid, 'drawdown-protect-forests',
     'Your summary with links to the maps and agency pages.',
     'Research online, and if you visit, stay on marked trails and follow posted rules.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/protect-forests), used with permission; assessment "Protect Forests- Solution Assessment Spreadsheet" by Avery Driscoll and Megan Matthews, https://doi.org/10.5281/zenodo.21230935, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'We define the Protect Forests solution as the long-term protection of tree-dominated ecosystems through establishment of protected areas (PAs), managed with the primary goal of conserving nature, and land tenure for Indigenous peoples. These protections reduce forest degradation, avoiding GHG emissions and ensuring continued carbon sequestration by healthy forests. This solution addresses protection of forests on mineral soils.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/protect-forests', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21230935'),
    ('b2a88b65-1e5b-5da4-9af7-011ca8f7874f'::uuid, 'drawdown-protect-grasslands-savannas',
     'Your map with links to the sources.',
     'Research online, and if you visit, stay on marked trails and follow posted rules.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/protect-grasslands-savannas), used with permission; assessment "Protect Grasslands and Savannas- Solution Assessment Spreadsheet" by Avery Driscoll and Christina Richardson, https://doi.org/10.5281/zenodo.21246118, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'This solution focuses on the legal protection of grassland and savanna ecosystems through the establishment of protected areas (PAs), which are managed with the primary goal of conserving nature, and land tenure for Indigenous peoples. These protections reduce grassland degradation, which preserves carbon stored in soils and vegetation and enables continued carbon sequestration by healthy grasslands.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/protect-grasslands-savannas', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246118'),
    ('f0533986-f7c6-53bd-82b4-c311e9875cb3'::uuid, 'drawdown-protect-peatlands',
     'A photo of your notes or a list of the products you checked.',
     'Read labels without opening bags, and don''t tell anyone which brand they must buy.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/protect-peatlands), used with permission; assessment "Protect Peatlands- Solution Assessment Spreadsheet" by Avery Driscoll and Megan Matthews, https://doi.org/10.5281/zenodo.21245970, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'The Protect Peatlands solution is defined as legally protecting peatland ecosystems through establishment of protected areas (PAs), which preserves stored carbon and ensures continued carbon sequestration by reducing degradation of the natural hydrology, soils, and/or vegetation. This solution focuses on non-coastal peatlands that have not yet been drained or otherwise severely degraded.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/protect-peatlands', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21245970'),
    ('960f0604-0a15-5012-aef8-a70418b535e3'::uuid, 'drawdown-protect-seaweed-ecosystems',
     'A link to your video, slideshow or comic with sources.',
     'Use your own footage or clips you have permission to use, and don''t harvest seaweed or dive for this mission.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/protect-seaweed-ecosystems), used with permission; assessment "Protect Seaweed Ecosystems- Solution Assessment Spreadsheet" by Christina Richardson and Avery Driscoll, https://doi.org/10.5281/zenodo.21245985, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Seaweed ecosystem protection is the long-term protection from degradation of wild subtidal brown and red seaweed ecosystems. Seaweeds, also called macroalgae, are photosynthetic marine organisms that absorb CO₂ from the water and convert it into biomass. This can lower surface-water CO₂ concentrations, allowing additional CO₂ from the atmosphere to be dissolved in the ocean.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/protect-seaweed-ecosystems', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21245985'),
    ('216568f0-243f-5cac-91b9-4b4ae8b571ed'::uuid, 'drawdown-restore-forests',
     'A photo of your work, with no one else''s face unless they agreed, or a link to where you shared the event.',
     'Plant only with an organized group that has the landowner''s permission, wear gloves and sturdy shoes, and follow the leaders'' safety briefing.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-forests), used with permission; assessment "Restore Forests- Solution Assessment Spreadsheet" by Avery Driscoll and Megan Matthews, https://doi.org/10.5281/zenodo.22002754, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Forest restoration is the process of returning previously forested land to a forested state. As forests regrow, they remove carbon from the atmosphere and sequester it in biomass.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-forests', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.22002754'),
    ('5b79bc68-40a5-5a3a-835f-23ab6b83e99e'::uuid, 'drawdown-restore-peatlands',
     'Your summary with links to the project.',
     'Bogs can be dangerous to walk on, so if you visit, stay on boardwalks and marked paths at public sites.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-peatlands), used with permission; assessment "Restore Peatlands- Solution Assessment Spreadsheet" by Avery Driscoll and Christina Richardson, https://doi.org/10.5281/zenodo.23377700, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Peatland restoration is the process of returning peat-forming vegetation and natural hydrologic conditions to degraded peatlands. Restoration of peatlands stops GHG emissions from peat degradation and removes carbon through sequestration in biomass and peat.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-peatlands', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.23377700'),
    ('1c2eaace-0753-5afa-b538-dc8989ed529e'::uuid, 'drawdown-deploy-silvopasture',
     'A photo of your labeled drawing or painting.',
     'Use your own artwork, and if you visit a farm, go only with the farmer''s invitation and keep away from livestock.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/deploy-silvopasture), used with permission; assessment "Deploy Silvopasture- Solution Assessment Spreadsheet" by Eric Toensmeier, https://doi.org/10.5281/zenodo.21246087, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'We define the Deploy Silvopasture solution as the adoption of agroforestry practices that add trees to grazing land, including planted pastures and natural rangelands. (Note that this solution does NOT include creating forested grazing land by thinning existing forest; this is a form of deforestation and not desirable in terms of climate.)',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/deploy-silvopasture', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246087'),
    ('60df48e0-d185-5852-99ae-7bf2a245e853'::uuid, 'drawdown-use-biochar',
     'A short summary of the conversation, without names unless people agreed.',
     'Don''t try to make biochar yourself, since it involves fire; just ask and share what you learn.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/use-biochar), used with permission; assessment "Use Biochar- Solution Assessment Spreadsheet" by Jason Lam and Megan Matthews, https://doi.org/10.5281/zenodo.23377743, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Producing biochar is the process of taking organic matter such as crop residues, animal manure, and forest residues and converting it into a charcoal-like substance known as biochar. Producing biochar removes carbon from the atmosphere by transforming carbon absorbed by plants and animals into a highly stable form, preventing it from quickly returning to the atmosphere (Belmont & Sanchez, 2025).',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/use-biochar', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.23377743'),
    ('3a9da222-581a-51ec-b5ae-a2599c35f46d'::uuid, 'drawdown-boost-appliance-equipment-efficiency',
     'A link or photo of your explainer.',
     'Explain what the label shows and link to the official guide, without telling anyone which product to buy.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/boost-appliance-equipment-efficiency), used with permission. Adapted: the mission wording is original.',
     'Boosting the efficiency of appliances and equipment cuts GHG emissions by reducing the amount of electricity used to operate these devices. Efficiency improvements also lead to reduced peak demand, less strain on the electric grid, and potential utility savings for homeowners due to reduced electricity use.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/boost-appliance-equipment-efficiency', null, null, null),
    ('ff5325cd-8f20-5ccf-9949-089b806a1d54'::uuid, 'drawdown-improve-building-envelopes',
     'A photo or link to your list in the place you shared it.',
     'Link only to official program pages, post only where you have permission, don''t promise anyone they will qualify, and don''t give financial advice.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-building-envelopes), used with permission; assessment "Improve Building Envelopes- Solution Assessment Spreadsheet" by Henry Igugu and Nina F. Farac, https://doi.org/10.5281/zenodo.23377578, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Improve Building Envelopes cuts GHG emissions by enhancing the thermal resistance of the building shell, reducing unwanted heat exchange between the external environment and indoor spaces. These thermal improvements help decrease the amount of energy required to heat and cool buildings and the associated emissions.',
     'Solution summary © Project Drawdown, used with permission.',
